VALUES ('qin-r1', '康', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '文公，在位五十年。初行大夫葬礼制度，秦国渐有起色，国势平稳，为后世奠基，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦文公"}]'::jsonb, '文公', NULL, '秦文公')
