VALUES ('qin-r2', '立', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '宪公，迁都徙民，国有起色。在位十二年，秦国继续发展，国势渐强，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦宪公"}]'::jsonb, '宪公', NULL, '秦宪公')
