VALUES ('qin-r3', '曼', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '庶子，被立为君后不久为叔父武公所弑。在位仅五年，政局动荡，国势不稳，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/出子"}]'::jsonb, NULL, NULL, '出子')
