VALUES ('qin-r4', '说', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '武公，肃内政、平内乱。在位十九年，秦国渐稳，国势回升，为穆公霸业奠基，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦武公"}]'::jsonb, '武公', NULL, '秦武公')
