VALUES ('qin-r5', '嘉', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '德公，在位仅两年，迁雍都。旋即传位宣公，秦国政局平稳，国势尚可，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦德公"}]'::jsonb, '德公', NULL, '秦德公')
