VALUES ('qin-r6', '恬', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '宣公，在位十一年。秦国维持二流强国地位，国势平稳，无力争霸，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦宣公"}]'::jsonb, '宣公', NULL, '秦宣公')
