VALUES ('qin-r7', '载', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '成公，在位仅四年。旋即传位穆公，秦国迎来霸业时期，国势渐强，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦成公"}]'::jsonb, '成公', NULL, '秦成公')
