VALUES ('qin-r8', '任好', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '在位三十九年，霸西戎，为春秋五霸之一。晚年兵败晋国，国力由盛转衰，霸业渐失，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦穆公"}]'::jsonb, '穆公', NULL, '秦穆公')
