VALUES ('qin-r9', '罃', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '康公，穆公之子。在位十一年，秦国维持现状，国势平稳，无力争霸，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦康公"}]'::jsonb, '康公', NULL, '秦康公')
