VALUES ('qin-r17', '欣', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '躁公，在位十四年。秦国继续衰落，国势危急，无力外争，濒临灭亡，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦躁公"}]'::jsonb, '躁公', NULL, '秦躁公')
