VALUES ('qin-r18', '封', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '怀公，被庶长所弑。在位仅数年，政局动荡，秦国内乱，国势不稳，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦怀公"}]'::jsonb, '怀公', NULL, '秦怀公')
