VALUES ('qin-r19', '肃', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '灵公，在位十三年。死后献公不得立，传位简公，政局动荡，国势转弱，事迹载于《史记》相关记载。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦灵公"}]'::jsonb, '灵公', NULL, '秦灵公')
