VALUES ('qin-r20', '悼子', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '简公，令吏带剑、初开徭。在位十五年，略有革新，国势渐起，为献公奠基，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦简公"}]'::jsonb, '简公', NULL, '秦简公')
