VALUES ('qin-r21', '仁', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '惠公（战国），伐蜀取南郑。在位十二年，旋即传位出公，秦国继续扩张，国势渐强，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦惠公"}]'::jsonb, '惠公', NULL, '秦惠公')
