VALUES ('qin-r22', '昌', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '童主，被庶长改迎献公所弑。在位仅两年，河西地为晋所夺，国势危急，濒临衰落，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦出公"}]'::jsonb, '出公', NULL, '秦出公')
