VALUES ('qin-r25', '驷', ARRAY[]::text[], '嬴', '赵', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['君主'], '杀商鞅而沿用其法，灭巴蜀，臣平周王。秦国首称王号，国势强盛，为统一奠基，事迹见《史记》。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/秦惠文王"}]'::jsonb, '惠文王', NULL, '秦惠文王')
