VALUES ('bian-que', '扁鹊', ARRAY[]::text[], NULL, NULL, -407, 1, NULL, 'year', -310, 1, NULL, 'year', ARRAY['医学家'], '战国名医，传说本名秦越人，因医术高明而被尊称扁鹊。史籍记载其周游行医，善察病情并采用多种疗法；望、闻、问、切四诊与其联系主要见于后世医史叙述。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/扁鹊"}]'::jsonb, NULL, NULL, NULL)
